#!/usr/bin/env python3
"""Generate the browser ABI from the pinned Foundry build; no downloads or wallet access."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def sync():
    artifact = json.loads((ROOT / 'out/IMDPot.sol/IMDPot.json').read_text())
    (ROOT / 'web/game-abi.mjs').write_text(
        '// Generated by tools/sync_abi.py from out/IMDPot.sol/IMDPot.json.\n'
        + 'export const gameAbi = ' + json.dumps(artifact['abi'], indent=2) + ';\n'
    )


if __name__ == '__main__':
    sync()
